"""Write docs/api-v2.schema.json from the v2 models. Run from api/: python scripts/export_v2_schema.py"""
import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
from models.assess import AssessRequest, AssessResponse  # noqa: E402

OUT = Path(__file__).resolve().parents[2] / "docs" / "api-v2.schema.json"


def build() -> dict:
    return {
        "$comment": "Generated by api/scripts/export_v2_schema.py from api/models/assess.py. Do not edit by hand.",
        "request": AssessRequest.model_json_schema(),
        "response": AssessResponse.model_json_schema(),
    }


if __name__ == "__main__":
    OUT.write_text(json.dumps(build(), indent=2, sort_keys=True) + "\n")
    print(f"wrote {OUT}")
